```javascript
res.format = function(obj) {
  var req = this.req;
  var types = Object.keys(obj);

  var best = req.accepts(types);
  if (best) {
    this.set('Content-Type', best);
    obj[best](req, this);
    return;
  }

  var notAcceptable = httpErrors(406);
  for (var type of types) {
    if (type.indexOf('*/*') !== -1 || type.indexOf('/*') !== -1) {
      this.set('Content-Type', type);
      obj[type](req, this);
      return;
    }
  }

  next(notAcceptable);
};
```

```javascript
res.format = function(obj) {
  var req = this.req;
  var type = req.accepts().types();
  var key = type[0] && type[0].split('/').shift();

  for (var i = 0; i < type.length; ++i) {
    var val = obj[type[i]];
    if (val) {
      this.set('Content-Type', type[i]);
      return val.call(this);
    }
  }

  if (obj.default) {
    this.set('Content-Type', 'application/octet-stream');
    return obj.default.call(this);
  }

  this.status(406).send('Not Acceptable');
};
```

