res.format = function(obj) {
  var req = this.req;
  var next = req.next;
  var types = Object.keys(obj);

  // remove Accept from headers since now handled
  delete req.headers.accept;

  // get accepted types for this request
  var acceptedTypes = acceptTypes(req.accepts(types));

  // get the most acceptable type
  var type = acceptedTypes[0];

  // default to first type
  if (!type) type = types[0];

  // if no types, respond with 406
  if (!type) {
    return this.status(406).send('Not Acceptable');
  }

  // respond with the negotiated type
  this.set('Content-Type', type);
  obj[type]();
};
```

